// src/app/api/contact/route.ts
import { NextResponse } from 'next/server';

export async function POST(request: Request) {
  try {
    const body = await request.json();
    // Simple validation – ensure required fields exist
    if (!body.name || !body.email || !body.message) {
      return NextResponse.json({ success: false, error: 'Invalid payload' }, { status: 400 });
    }
    // Simulate processing delay
    await new Promise((resolve) => setTimeout(resolve, 500));
    return NextResponse.json({ success: true }, { status: 200 });
  } catch (e) {
    return NextResponse.json({ success: false, error: 'Server error' }, { status: 500 });
  }
}

"use client";
import { useState } from 'react';
import { useForm } from 'react-hook-form';
import { z } from 'zod';
import { zodResolver } from '@hookform/resolvers/zod';

const schema = z.object({
  name: z.string().min(2, 'Name is required'),
  email: z.string().email('Invalid email'),
  message: z.string().min(10, 'Message too short'),
});

type FormData = z.infer<typeof schema>;

export const ContactForm = () => {
  const [status, setStatus] = useState<'idle' | 'loading' | 'success' | 'error'>('idle');
  const {
    register,
    handleSubmit,
    formState: { errors },
    reset,
  } = useForm<FormData>({ resolver: zodResolver(schema) });

  const onSubmit = async (data: FormData) => {
    setStatus('loading');
    try {
      const res = await fetch('/api/contact', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(data),
      });
      const json = await res.json();
      if (json.success) {
        setStatus('success');
        reset();
      } else {
        setStatus('error');
      }
    } catch (e) {
      setStatus('error');
    }
  };

  return (
    <section className="py-24 bg-[#0A0A0A] text-primary" id="contact">
      <h2 className="text-center text-4xl font-heading mb-12">GET IN TOUCH</h2>
      <form
        onSubmit={handleSubmit(onSubmit)}
        className="max-w-xl mx-auto space-y-6 px-6"
        noValidate
      >
        <div>
          <input
            type="text"
            placeholder="Name"
            {...register('name')}
            className="w-full p-3 bg-[#1A1A1A] border border-[rgba(244,241,234,0.15)] text-primary placeholder:text-secondary focus:outline-none focus:border-accent"
          />
          {errors.name && <p className="text-sm text-red-400 mt-1">{errors.name.message}</p>}
        </div>
        <div>
          <input
            type="email"
            placeholder="Email"
            {...register('email')}
            className="w-full p-3 bg-[#1A1A1A] border border-[rgba(244,241,234,0.15)] text-primary placeholder:text-secondary focus:outline-none focus:border-accent"
          />
          {errors.email && <p className="text-sm text-red-400 mt-1">{errors.email.message}</p>}
        </div>
        <div>
          <textarea
            placeholder="Message"
            rows={5}
            {...register('message')}
            className="w-full p-3 bg-[#1A1A1A] border border-[rgba(244,241,234,0.15)] text-primary placeholder:text-secondary focus:outline-none focus:border-accent"
          />
          {errors.message && <p className="text-sm text-red-400 mt-1">{errors.message.message}</p>}
        </div>
        <button
          type="submit"
          disabled={status === 'loading'}
          className="w-full py-3 bg-accent text-[#0A0A0A] font-heading hover:bg-accent/90 transition-colors disabled:opacity-50"
        >
          {status === 'loading' ? 'Sending...' : 'Send Message'}
        </button>
        {status === 'success' && <p className="text-green-400 mt-2">Message sent successfully!</p>}
        {status === 'error' && <p className="text-red-400 mt-2">Oops! Something went wrong.</p>}
      </form>
    </section>
  );
};

"use client";
import { useEffect, useRef } from 'react';
import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

if (typeof window !== 'undefined') {
  gsap.registerPlugin(ScrollTrigger);
}

export const Hero = () => {
  const heroRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!heroRef.current) return;
    const ctx = gsap.context(() => {
      const tl = gsap.timeline({ defaults: { ease: 'power3.out' } });
      tl.from('.badge', { y: -30, opacity: 0, duration: 0.6 })
        .from('.headline', { y: 50, opacity: 0, stagger: 0.2, duration: 0.8 })
        .from('.subtext', { y: 20, opacity: 0, duration: 0.5 })
        .from('.cta', { y: 20, opacity: 0, stagger: 0.2, duration: 0.5 }, '-=0.3');
    }, heroRef);
    return () => ctx.revert();
  }, []);

  return (
    <section ref={heroRef} className="relative flex min-h-screen flex-col items-center justify-center text-center px-6 py-24 bg-[#0A0A0A] text-primary">
      <div className="badge text-sm uppercase tracking-widest text-accent mb-4">AVAILABLE FOR FREELANCE PROJECTS</div>
      <h1 className="headline text-5xl md:text-7xl font-heading font-bold mb-6">
        BUILDING DIGITAL<br />EXPERIENCES THAT MOVE.
      </h1>
      <p className="subtext max-w-2xl mx-auto text-lg md:text-xl mb-8">
        Freelance Full Stack Developer creating modern websites, e‑commerce experiences and web applications using React, Next.js and Shopify.
      </p>
      <div className="cta flex flex-col md:flex-row gap-4 justify-center">
        <Link href="#contact" className="inline-flex items-center gap-2 rounded-full bg-accent px-6 py-3 text-black font-medium hover:scale-105 transition-transform">
          START A PROJECT <span aria-hidden="true">→</span>
        </Link>
        <Link href="#work" className="inline-flex items-center gap-2 rounded-full border border-accent px-6 py-3 text-primary hover:bg-accent hover:text-black transition-colors">
          VIEW SELECTED WORK ↓
        </Link>
      </div>
    </section>
  );
};

"use client";

import Link from 'next/link';
// Image component removed; using standard img tag
import { ArrowRight, Globe, ShoppingBag, Code, Zap } from 'lucide-react';
import { useEffect, useRef } from 'react';
import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

if (typeof window !== 'undefined') {
  gsap.registerPlugin(ScrollTrigger);
}

type ProjectCardProps = {
  slug: string;
  title: string;
  category: string;
  description: string;
  technologies: string[];
  image: string;
  link: string;
};

export const ProjectCard: React.FC<ProjectCardProps> = ({ slug, title, category, description, technologies, image, link }) => {
  const cardRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!cardRef.current) return;
    const ctx = gsap.context(() => {
      const tl = gsap.timeline({ defaults: { ease: 'power3.out' } });
      tl.from(cardRef.current, { opacity: 0, y: 30, duration: 0.6 });
    }, cardRef);
    return () => ctx.revert();
  }, []);

  return (
    <div ref={cardRef} className="group relative overflow-hidden rounded-lg border border-[rgba(244,241,234,0.15)] project-card">
      <Link href={`/work/${slug}`}> 
        <img src={image} alt={title} width="800" height="500" className="w-full h-auto object-cover transition-transform duration-300 group-hover:scale-105" />
        <div className="absolute inset-0 bg-black bg-opacity-30 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
          <span className="text-xl font-heading text-accent bg-white bg-opacity-10 px-4 py-2 rounded">VIEW</span>
        </div>
      </Link>
      <div className="p-4 bg-[#0A0A0A] text-primary">
        <h3 className="font-heading text-lg mb-1">{title}</h3>
        <p className="text-sm text-secondary mb-2">{category}</p>
        <p className="text-sm mb-2 line-clamp-2">{description}</p>
        <div className="flex flex-wrap gap-2 text-xs">
          {technologies.map((tech) => (
            <span key={tech} className="bg-accent bg-opacity-20 px-2 py-1 rounded">{tech}</span>
          ))}
        </div>
      </div>
    </div>
  );
};

"use client";
import Link from 'next/link';
import { ArrowRight, Globe, ShoppingBag, Code, Zap } from 'lucide-react';
import { useEffect, useRef } from 'react';
import { gsap } from 'gsap';

// Map icon names to Lucide components
const iconMap: Record<string, React.ComponentType<any>> = {
  Globe,
  ShoppingBag,
  Code,
  Zap,
};

type ServiceCardProps = {
  title: string;
  description: string;
  icon: string; // name of Lucide icon
};

export const ServiceCard: React.FC<ServiceCardProps> = ({ title, description, icon }) => {
  const cardRef = useRef<HTMLDivElement>(null);
  const IconComponent = iconMap[icon] || null;

  useEffect(() => {
    if (!cardRef.current) return;
    const ctx = gsap.context(() => {
      gsap.from(cardRef.current, { opacity: 0, y: 30, duration: 0.6, ease: 'power3.out' });
    }, cardRef);
    return () => ctx.revert();
  }, []);

  return (
    <div
      ref={cardRef}
      className="group relative rounded-lg border border-[rgba(244,241,234,0.15)] p-6 text-primary transition-colors hover:border-accent"
    >
      {IconComponent && <IconComponent className="h-8 w-8 text-accent mb-4" />}
      <h3 className="font-heading text-xl mb-2">{title}</h3>
      <p className="text-sm text-secondary mb-4 opacity-0 group-hover:opacity-100 transition-opacity duration-300">
        {description}
      </p>
      <Link href="#contact" className="inline-flex items-center gap-1 text-accent font-medium">
        Learn More <ArrowRight size={16} />
      </Link>
    </div>
  );
};
